use super::*;
#[path="../../../🧳️state/🧪️tests/🧰️helpers/🦀️.rs"]mod helpers;
use helpers::{grant,observe,denied_axes,drain};
#[test]
fn authored_empty_native_genesis_preserves_each_denied_currency_and_closes_every_original_birth_prefix(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for cutoff in std::iter::once(None).chain(law["cancelAt"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize))){let(mut cursor,heap)=observe(EnergyModelInitialBirth::new);assert_eq!(heap,(0,0));assert!(2*size_of::<EnergyModelInitialBirth>()<=4096);let mut turns=0;while !cursor.ready()&&cutoff.is_none_or(|cut|turns<cut){let d=cursor.demand(4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(step,h)=observe(||cursor.advance(4096,denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(cursor.demand(4096).unwrap(),d);}let(step,h)=observe(||cursor.advance(4096,g).unwrap());assert!(step.progress().fits(g));assert_eq!(h,(step.progress().retained_capacity_bytes,step.progress().released_bytes));turns+=1;assert!(turns<=20);}
 let mut output=None;if cutoff.is_none(){let d=cursor.take_demand().unwrap();let g=grant(d);for denied in denied_axes(g,d){let(result,h)=observe(||cursor.take(denied).unwrap());assert!(result.is_none());assert_eq!(h,(0,0));}let((state,p),h)=observe(||cursor.take(g).unwrap().unwrap());assert!(p.fits(g));assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));let model=state.model.read();assert_eq!(state.schema.get(),law["schema"].as_str().unwrap());assert_eq!(model.name,law["name"].as_str().unwrap());assert_eq!(model.version,law["version"].as_str().unwrap());assert_eq!(model.site.latitude_deg,0.0);assert_eq!(model.ground_temperature.building_surface_c.get(),&[18.0;12]);assert_eq!(model.ground_temperature.shallow_c.get(),&[18.0;12]);assert_eq!(model.ground_temperature.deep_c,18.0);assert_eq!(model.run_period.year,2026);assert!(model.zones.is_empty());assert!(model.fenestrations.is_empty());assert!(model.battery_storage.is_empty());assert!(model.schedules.constants.is_empty());assert!(state.weather_link.get().is_none());assert!(state.referenced_model.get().is_none());output=Some(state);}
 cursor.begin_close();for _ in 0..10000{if cursor.terminal_is_empty(){break;}let d=cursor.close_demand(4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(step,h)=observe(||cursor.close_step(denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(cursor.close_demand(4096).unwrap(),d);}let(step,h)=observe(||cursor.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(h,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(cursor.terminal_is_empty());assert_eq!(observe(||drop(cursor)).1,(0,0));if let Some(state)=output{drain(state);}}
}

#[test]
fn original_body_policy_begins_only_on_the_first_funded_source_advance(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let policy=&law["bodyPolicy"];let admitted=policy["admitted"].as_u64().unwrap()as usize;let foreign=policy["foreign"].as_u64().unwrap()as usize;let mut cursor=EnergyModelInitialBirth::new();let d=cursor.demand(policy["unfunded"].as_u64().unwrap()as usize).unwrap();let mut denied=grant(d);denied.maximum_items=0;let(step,h)=observe(||cursor.advance(policy["unfunded"].as_u64().unwrap()as usize,denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(h,(0,0));let d=cursor.demand(admitted).unwrap();let(step,h)=observe(||cursor.advance(admitted,grant(d)).unwrap());assert_eq!(step.progress().copied_bytes,d.copy_bytes);assert_eq!(h,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(cursor.demand(foreign).is_err());cursor.begin_close();for _ in 0..10000{if cursor.terminal_is_empty(){break;}let d=cursor.close_demand(admitted).unwrap();assert_eq!(cursor.close_demand(foreign).unwrap(),d);let g=grant(d);for denied in denied_axes(g,d){let(step,h)=observe(||cursor.close_step(denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(h,(0,0));}let(step,h)=observe(||cursor.close_step(g).unwrap());assert_eq!(h,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(cursor.terminal_is_empty());}
